import{_ as a,o as s,c as i,a2 as e}from"./chunks/framework.BbQrW5_t.js";const u=JSON.parse('{"title":"CTF 入门","description":"","frontmatter":{"title":"CTF 入门","date":"2026-09-03T00:00:00.000Z","tags":["网络安全","初级"]},"headers":[],"relativePath":"study/cyber-security/chapters/初级篇/06-CTF入门.md","filePath":"study/cyber-security/chapters/初级篇/06-CTF入门.md","lastUpdated":1788493831000}'),d={name:"study/cyber-security/chapters/初级篇/06-CTF入门.md"};function l(n,t,r,o,h,p){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="_06-·-ctf-入门——合法的-实战手感-来源" tabindex="-1">06 · CTF 入门——合法的&quot;实战手感&quot;来源 <a class="header-anchor" href="#_06-·-ctf-入门——合法的-实战手感-来源" aria-label="Permalink to &quot;06 · CTF 入门——合法的&quot;实战手感&quot;来源&quot;">​</a></h1><blockquote><p>CTF 是攻防技能唯一合法的&quot;无限量&quot;练习场。目标不是打比赛名次，而是用题目把前面五章的知识<strong>串成条件反射</strong>。</p></blockquote><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><ol><li>说出五大题型的技能需求与你的主攻优先级</li><li>独立完成一道 Web 题的完整 Writeup</li><li>建立&quot;从提示到 payload&quot;的解题反射</li><li>制订 30 天刷题路线并执行</li></ol><h2 id="📖-核心知识" tabindex="-1">📖 核心知识 <a class="header-anchor" href="#📖-核心知识" aria-label="Permalink to &quot;📖 核心知识&quot;">​</a></h2><h3 id="_6-1-题型地图-结合你的背景排优先级" tabindex="-1">6.1 题型地图（结合你的背景排优先级） <a class="header-anchor" href="#_6-1-题型地图-结合你的背景排优先级" aria-label="Permalink to &quot;6.1 题型地图（结合你的背景排优先级）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>题型</th><th>技能需求</th><th>对你的难度</th><th>优先级</th></tr></thead><tbody><tr><td>Web</td><td>HTTP/OWASP/PHP 特性</td><td>低（有代码底子）</td><td>⭐⭐⭐⭐⭐ 主攻</td></tr><tr><td>Misc</td><td>隐写/编码/流量分析</td><td>低-中</td><td>⭐⭐⭐⭐ 次攻</td></tr><tr><td>Crypto</td><td>数论/编码/现成库</td><td>中</td><td>⭐⭐⭐ 跟进</td></tr><tr><td>Reverse</td><td>汇编/逆向工具</td><td>高（新领域）</td><td>⭐⭐ 后置</td></tr><tr><td>Pwn</td><td>汇编/内存/OS</td><td>最高</td><td>⭐ 第 2 年再碰</td></tr></tbody></table><h3 id="_6-2-解题方法论-反射训练" tabindex="-1">6.2 解题方法论（反射训练） <a class="header-anchor" href="#_6-2-解题方法论-反射训练" aria-label="Permalink to &quot;6.2 解题方法论（反射训练）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>看到 URL/页面</span></span>
<span class="line"><span>  1. 信息收集：源码注释? robots.txt? .git/.svn? 备份文件(index.php.bak)?</span></span>
<span class="line"><span>  2. 指纹识别：什么框架/语言/中间件（响应头/报错页/图标）</span></span>
<span class="line"><span>  3. 参数面：所有输入点（GET/POST/Cookie/Header）逐一标记</span></span>
<span class="line"><span>  4. 漏洞匹配：参数类型 ↔ 漏洞族（数字→注入? 文件名→上传/包含? 渲染→XSS/SSTI?）</span></span>
<span class="line"><span>  5. 利用与调参：改 payload、看响应差异（回显/时间/长度）</span></span>
<span class="line"><span>  6. flag：不是终点——写 Writeup 才是</span></span></code></pre></div><h3 id="_6-3-writeup-标准写法-示例-robots-txt-泄露题" tabindex="-1">6.3 Writeup 标准写法（示例：robots.txt 泄露题） <a class="header-anchor" href="#_6-3-writeup-标准写法-示例-robots-txt-泄露题" aria-label="Permalink to &quot;6.3 Writeup 标准写法（示例：robots.txt 泄露题）&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 题目：Web_01（100pt）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 信息收集</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 首页无异常；查看 /robots.txt：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Disallow: /f1ag_1s_h3re.html</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 利用</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 直接访问 /f1ag_1s_h3re.html → 页面注释中有 flag</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 知识点</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> robots.txt 是给搜索引擎的&quot;访客止步&quot;清单，默认公开——反而成了路标</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 反思</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 信息收集永远先看&quot;公开就能拿到&quot;的东西，再上工具</span></span></code></pre></div><p>公式：<strong>信息收集 → 利用过程 → 知识点 → 反思</strong>。反思段是给你自己三个月后看的。</p><h3 id="_6-4-工具清单表" tabindex="-1">6.4 工具清单表 <a class="header-anchor" href="#_6-4-工具清单表" aria-label="Permalink to &quot;6.4 工具清单表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>工具</th></tr></thead><tbody><tr><td>代理抓包</td><td>Burp Suite</td></tr><tr><td>目录爆破</td><td>dirsearch / 自研（第 4 模块产出）</td></tr><tr><td>编解码</td><td>CyberChef（神器）、base64/rot13/URL</td></tr><tr><td>编码脚本</td><td>Python 一把梭（你已有的优势）</td></tr><tr><td>题库</td><td>攻防世界、Bugku、PicoCTF</td></tr></tbody></table><h3 id="_6-5-新手-30-天刷题路线" tabindex="-1">6.5 新手 30 天刷题路线 <a class="header-anchor" href="#_6-5-新手-30-天刷题路线" aria-label="Permalink to &quot;6.5 新手 30 天刷题路线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>天</th><th>任务</th></tr></thead><tbody><tr><td>1-5</td><td>攻防世界新手区：view_source / robots / backup / cookie / disable_cache</td></tr><tr><td>6-10</td><td>新手区：简单 SQLi ×3、XSS ×2（全部手工，禁 sqlmap）</td></tr><tr><td>11-15</td><td>Bugku Web：302 跳转、头信息伪造、程序员本地网站</td></tr><tr><td>16-20</td><td>Misc 入门：图片隐写（binwalk/strings/stegsolve）×5</td></tr><tr><td>21-25</td><td>Crypto 入门：摩斯/Base 全家桶/栅栏/凯撒 ×5</td></tr><tr><td>26-30</td><td>综合复盘：重做最难的 3 题 + 整理 3 篇 Writeup 发布</td></tr></tbody></table><h2 id="🔬-动手实操" tabindex="-1">🔬 动手实操 <a class="header-anchor" href="#🔬-动手实操" aria-label="Permalink to &quot;🔬 动手实操&quot;">​</a></h2><p>注册攻防世界 → 新手区 → 严格按 6.2 方法论做前 3 题，每题产出标准 Writeup，发到知识库 <code>docs/study/cyber-security/writeups/</code>。</p><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ol><li>直接搜 flag/看题解——大脑跳过了建立反射的关键步骤</li><li>只刷 Web 不碰 Misc——Misc 练的是&quot;信息敏感度&quot;，全题型通用</li><li>Writeup 只写 payload 不写思路——三个月后你自己都看不懂</li><li>攻击性 payload 对着非靶场地址试——CTF 平台的题目地址才是授权范围</li><li>贪多求快——30 题吃透 &gt; 100 题打卡</li></ol><h2 id="✅-自测题" tabindex="-1">✅ 自测题 <a class="header-anchor" href="#✅-自测题" aria-label="Permalink to &quot;✅ 自测题&quot;">​</a></h2><details><summary>1. 为什么robots.txt 常成为 Web 题突破口？</summary><p>它本身公开可读，但列出的 Disallow 路径=站长不想被看到的敏感目录清单，直接变成攻击者路标。</p></details><details><summary>2. Web 题里&quot;参数类型↔漏洞族&quot;怎么匹配？</summary><p>数字 ID→SQL 注入（数字型）；文件名/路径→上传/包含/遍历；内容渲染→XSS/SSTI；URL 参数→SSRF；Cookie/JWT→越权与会话缺陷。</p></details><details><summary>3. Writeup 中&quot;反思&quot;为什么重要？</summary><p>把单题经验抽象成可迁移的模式（如&quot;先看公开信息再上工具&quot;），这是从做题者到工程师的分水岭。</p></details><details><summary>4. Misc 题对 Web 手的帮助是什么？</summary><p>训练信息敏感度与工具箱广度（strings/binwalk/file），Web 题里的图片/附件/流量包全靠这套基本功。</p></details><details><summary>5. 为什么禁 sqlmap 刷新手题？</summary><p>新手题的 payload 都能手工构造；先手工建立&quot;注入是什么&quot;的肌肉记忆，工具才有正确的使用场景（省时间而非替你思考）。</p></details><h2 id="🔗-对应周任务与资源" tabindex="-1">🔗 对应周任务与资源 <a class="header-anchor" href="#🔗-对应周任务与资源" aria-label="Permalink to &quot;🔗 对应周任务与资源&quot;">​</a></h2><ul><li>对应计划：<strong>第1年 W18-W21、W41</strong>；资源：CTF Wiki（ctf-wiki.org）、攻防世界、PicoCTF</li></ul>`,28)])])}const k=a(d,[["render",l]]);export{u as __pageData,k as default};
